module fence_posts (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [3:0] K,\n    input wire [3:0] N,\n    input wire [7:0] p [0:7],\n    output reg [7:0] cuts,\n    output reg done\n);\n\n    // State declarations\n    localparam [2:0] IDLE         = 3'd0;\n    localparam [2:0] FIND_L       = 3'd1;\n    localparam [2:0] CHECK_L      = 3'd2;\n    localparam [2:0] COMPUTE_D    = 3'd3;\n    localparam [2:0] SORT_D       = 3'd4;\n    localparam [2:0] FIND_T       = 3'd5;\n    localparam [2:0] CALC_RESULT  = 3'd6;\n    localparam [2:0] DONE_STATE   = 3'd7;\n\n    reg [2:0] state, next_state;\n    reg [7:0] L;\n    reg [7:0] max_L;\n    reg [7:0] temp_sum;\n    reg [7:0] D [0:7];\n    reg [2:0] D_size;\n    reg [7:0] prefix_sum;\n    reg [2:0] t;\n    reg [7:0] cuts_reg;\n    reg [7:0] cycle_count;\n    reg [3:0] i, j;\n    reg [3:0] pole_idx;\n    reg [2:0] sort_rounds;\n    reg [3:0] D_idx;\n    reg [7:0] temp_D;\n    reg [3:0] check_L_counter;\n    reg [7:0] div_a, div_count;\n    reg [7:0] mod_a;\n    reg div_busy, mod_busy;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            cuts <= 8'd0;\n            cuts_reg <= 8'd0;\n            L <= 8'd0;\n            max_L <= 8'd0;\n            temp_sum <= 8'd0;\n            for (i = 0; i < 8; i = i + 1) begin\n                D[i] <= 8'd0;\n            end\n            D_size <= 3'd0;\n            prefix_sum <= 8'd0;\n            t <= 3'd0;\n            cycle_count <= 8'd0;\n            pole_idx <= 4'd0;\n            sort_rounds <= 3'd0;\n            D_idx <= 4'd0;\n            temp_D <= 8'd0;\n            check_L_counter <= 4'd0;\n            div_a <= 8'd0;\n            div_count <= 8'd0;\n            mod_a <= 8'd0;\n            div_busy <= 1'b0;\n            mod_busy <= 1'b0;\n        end else begin\n            cycle_count <= cycle_count + 8'd1;\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    cycle_count <= 8'd0;\n                    if (start) begin\n                        state <= FIND_L;\n                        // Find initial max_L\n                        max_L <= p[0];\n                        for (i = 0; i < 8; i = i + 1) begin\n                            if (i < K && p[i] > max_L) begin\n                                max_L <= p[i];\n                            end\n                        end\n                        L <= max_L;\n                    end\n                end\n\n                FIND_L: begin\n                    state <= CHECK_L;\n                    temp_sum <= 8'd0;\n                    pole_idx <= 4'd0;\n                end\n\n                CHECK_L: begin\n                    if (pole_idx < K) begin\n                        // Compute floor(p[pole_idx]/L)\n                        div_a <= p[pole_idx];\n                        div_busy <= 1'b1;\n                        div_count <= 8'd0;\n                        while (div_a >= L && L != 0) begin\n                            div_a <= div_a - L;\n                            div_count <= div_count + 8'd1;\n                        end\n                        temp_sum <= temp_sum + div_count;\n                        pole_idx <= pole_idx + 4'd1;\n                    end else begin\n                        if (temp_sum >= N) begin\n                            state <= COMPUTE_D;\n                            D_size <= 3'd0;\n                            pole_idx <= 4'd0;\n                        end else begin\n                            if (L > 8'd0) begin\n                                L <= L - 8'd1;\n                                state <= FIND_L;\n                            end else begin\n                                // Invalid state, go to done\n                                state <= CALC_RESULT;\n                                cuts_reg <= N;\n                            end\n                        end\n                    end\n                end\n\n                COMPUTE_D: begin\n                    if (pole_idx < K) begin\n                        mod_a <= p[pole_idx];\n                        if (L != 0 && mod_a % L == 0) begin\n                            D[D_size] <= div_count;  // Previous div result\n                            D_size <= D_size + 3'd1;\n                        end\n                        pole_idx <= pole_idx + 4'd1;\n                    end else begin\n                        state <= SORT_D;\n                        sort_rounds <= 3'd0;\n                    end\n                end\n\n                SORT_D: begin\n                    if (sort_rounds < D_size) begin\n                        for (j = 0; j < D_size - 3'd1; j = j + 4'd1) begin\n                            if (D[j] > D[j+1]) begin\n                                temp_D <= D[j];\n                                D[j] <= D[j+1];\n                                D[j+1] <= temp_D;\n                            end\n                        end\n                        sort_rounds <= sort_rounds + 3'd1;\n                    end else begin\n                        state <= FIND_T;\n                        D_idx <= 4'd0;\n                        prefix_sum <= 8'd0;\n                        t <= 3'd0;\n                    end\n                end\n\n                FIND_T: begin\n                    if (D_idx < D_size) begin\n                        if (prefix_sum + D[D_idx] <= N) begin\n                            prefix_sum <= prefix_sum + D[D_idx];\n                            t <= t + 3'd1;\n                            D_idx <= D_idx + 4'd1;\n                        end else begin\n                            state <= CALC_RESULT;\n                        end\n                    end else begin\n                        state <= CALC_RESULT;\n                    end\n                end\n\n                CALC_RESULT: begin\n                    cuts_reg <= N - t;\n                    state <= DONE_STATE;\n                end\n\n                DONE_STATE: begin\n                    cuts <= cuts_reg;\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule